import {decorationCatalog,decorationColors,decorationIcon} from './decorations.js';
import {makePanel,communityRequest as request} from './panels.js';
const wishes=makePanel('wish-panel','소원',`<div class="wish-tabs" role="group" aria-label="소원 메뉴"><button type="button" data-wish-tab="write" aria-pressed="true">작성</button><button type="button" data-wish-tab="list" aria-pressed="false">소원 목록</button></div><form id="wish-form"><div class="wish-compose-head"><div class="wish-preview" aria-hidden="true"></div><div><span class="field-caption">트리 장식</span><p>모양과 색상을 골라 주세요</p></div></div><input type="hidden" name="kind" value="heart"><div class="wish-shapes" role="group" aria-label="장식 모양">${Object.entries(decorationCatalog).map(([id,item])=>`<button type="button" data-wish-kind="${id}" aria-label="${item.name}" title="${item.name}">${decorationIcon(id)}<span>${item.name}</span></button>`).join('')}</div><div class="wish-color-row"><div class="wish-swatches" role="group" aria-label="장식 색상">${decorationColors.map(color=>`<button type="button" data-wish-color="${color}" style="--swatch:${color}" aria-label="${color}"></button>`).join('')}<label class="wish-custom-color" aria-label="사용자 지정 색상"><input type="color" name="color" value="#e5bb6b" aria-label="사용자 지정 색상"><span>＋</span></label></div></div><label class="wish-message"><span>소원 <output data-count>0 / 160</output></span><textarea name="message" maxlength="160" rows="4" required placeholder="소원을 적어 주세요"></textarea></label><fieldset class="wish-privacy"><legend>공개 범위</legend><label><input type="radio" name="visibility" value="private" checked><span>나만 보기</span></label><label><input type="radio" name="visibility" value="public"><span>이 공간에 공개</span></label></fieldset><p class="fine-print">공개를 선택한 소원만 방문자에게 보입니다.</p><button class="panel-primary" type="submit">트리에 달기 <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></button><output role="status"></output></form><div id="wish-list" hidden></div>`);
window.addEventListener('lab:wish-submitted',()=>wishes.close());
const form=wishes.dialog.querySelector('form'),list=wishes.dialog.querySelector('#wish-list');
function previewWish(){const p=form.querySelector('.wish-preview'),color=form.elements.color.value;p.innerHTML=decorationIcon(form.elements.kind.value);p.style.color=color;form.querySelectorAll('[data-wish-kind]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.wishKind===form.elements.kind.value));form.querySelectorAll('[data-wish-color]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.wishColor.toLowerCase()===color.toLowerCase()));form.querySelector('.wish-custom-color').style.setProperty('--swatch',color);form.querySelector('.wish-custom-color').classList.toggle('selected',!decorationColors.includes(color));}
form.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.wishKind){form.elements.kind.value=b.dataset.wishKind;previewWish();}if(b?.dataset.wishColor){form.elements.color.value=b.dataset.wishColor;previewWish();}});
form.elements.color.addEventListener('input',previewWish);form.elements.message.addEventListener('input',()=>form.querySelector('[data-count]').textContent=form.elements.message.value.length+' / 160');previewWish();
window.addEventListener('lab:decoration-choice',e=>{if(decorationCatalog[e.detail.decoration])form.elements.kind.value=e.detail.decoration;if(/^#[0-9a-f]{6}$/i.test(e.detail.color))form.elements.color.value=e.detail.color;previewWish();});
function wishTab(tab){form.hidden=tab!=='write';list.hidden=tab!=='list';wishes.dialog.querySelectorAll('[data-wish-tab]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.wishTab===tab));}
wishes.dialog.querySelector('.wish-tabs').onclick=e=>{const tab=e.target.closest('[data-wish-tab]')?.dataset.wishTab;if(!tab)return;wishTab(tab);if(tab==='list')loadWishes();};
async function loadWishes(selected){list.textContent='불러오는 중…';try{await window.joinSharedActivity();const {wishes:items}=await request('wishes');list.replaceChildren();if(!items.length){list.textContent='아직 소원이 없습니다.';return;}for(const item of items){const card=document.createElement('article');card.className='wish-card';card.dataset.wish=item.id;const who=document.createElement('small'),text=document.createElement('p'),actions=document.createElement('div');who.textContent=item.name+' · '+new Intl.DateTimeFormat('ko-KR',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(item.createdAt))+(item.visibility==='private'?' · 나만 보기':'');const icon=document.createElement('span');icon.className='wish-card-icon';icon.innerHTML=decorationIcon(item.kind);icon.style.color=item.color||'#e5bb6b';card.append(icon);const show=document.createElement('button');show.textContent='장식 보기';show.onclick=()=>{wishes.close();window.dispatchEvent(new CustomEvent('lab:highlight-ornament',{detail:item.id}));};actions.append(show);text.textContent=item.message;card.append(who,text,actions);if(item.visibility==='public'){const react=document.createElement('button');react.textContent='♡ '+item.reactions;react.setAttribute('aria-label','소원에 하트');react.setAttribute('aria-pressed',!!item.reacted);react.onclick=async()=>{react.disabled=true;try{await request('wishes',{action:'react',id:item.id});await loadWishes(item.id);}catch(e){react.disabled=false;card.append(document.createTextNode(e.message));}};actions.append(react);}if(!item.mine){const report=document.createElement('button');report.textContent='신고';report.onclick=()=>reportContent({type:'wish',id:item.id});actions.append(report);}list.append(card);}if(selected)list.querySelector(`[data-wish="${CSS.escape(selected)}"]`)?.scrollIntoView({block:'nearest'});}catch(e){list.textContent=e.message;}}
window.openWishList=id=>{wishTab('list');wishes.open();loadWishes(id);};window.openWishComposer=()=>{wishTab('write');wishes.open();form.elements.message.focus();};
form.onsubmit=async e=>{
 e.preventDefault();const output=form.querySelector('output[role=status]'),button=form.querySelector('[type=submit]');if(button.disabled)return;
 const data={message:form.elements.message.value.trim(),visibility:form.elements.visibility.value,kind:form.elements.kind.value,color:form.elements.color.value};if(!data.message)return;
 button.disabled=true;output.textContent='';
 try{
  if(!window.submitTreeWish)throw Error('트리를 준비하고 있습니다. 잠시 후 다시 시도해 주세요.');
  await window.submitTreeWish(data);form.elements.message.value='';form.querySelector('[data-count]').textContent='0 / 160';wishes.close();
 }catch(err){output.textContent=err.message;}finally{button.disabled=false;}
};
const reportPanel=makePanel('report-panel','신고',`<form><label>사유<textarea name="reason" maxlength="200" rows="3" required placeholder="신고 사유"></textarea></label><button class="panel-primary">신고 보내기</button><output role="status"></output></form>`);let reportTarget;
function reportContent(target){reportTarget=target;reportPanel.dialog.querySelector('form').reset();reportPanel.dialog.querySelector('output').textContent='';reportPanel.open();}window.addEventListener('lab:report',e=>reportContent(e.detail));reportPanel.dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const output=reportPanel.dialog.querySelector('output'),button=e.target.querySelector('button');button.disabled=true;try{await request('reports',{...reportTarget,reason:e.target.elements.reason.value});output.textContent='신고를 접수했습니다.';e.target.reset();}catch(err){output.textContent=err.message;}finally{button.disabled=false;}};
const adminPanel=makePanel('admin-panel','관리',`<div class="panel-row"><button data-refresh>새로고침</button><output role="status"></output></div><details open><summary>신고</summary><div data-reports></div></details><details><summary>접속자 · 채팅</summary><div data-people></div></details><details><summary>트리 장식</summary><div data-decorations></div></details><details><summary>퀴즈 관리</summary><div data-quizzes></div><form data-quiz-form><input name="id" type="hidden"><label>문제<input name="question" maxlength="240" required></label><label>분야<select name="category"><option>과학</option><option>역사</option><option>지리</option><option>동물</option><option>자연</option><option>예술</option><option>일반</option></select></label>${[1,2,3,4].map(n=>`<label>보기 ${n}<input name="option${n}" maxlength="120" required></label>`).join('')}<label>정답<select name="answer">${[0,1,2,3].map(n=>`<option value="${n}">${n+1}번</option>`).join('')}</select></label><label>해설<textarea name="explanation" maxlength="1000" required></textarea></label><label>출처 제목<input name="sourceTitle" required></label><label>출처 링크<input type="url" name="sourceURL" required></label><label class="check-label"><input type="checkbox" name="disabled">출제 중지</label><button class="panel-primary">문제 저장</button></form></details><details><summary>이벤트 관리</summary><div data-events></div><form data-event-form><label>이름<input name="title" maxlength="60" required></label><label>종류<select name="kind"><option value="lights">조명 공연</option><option value="quiz">퀴즈 시간</option><option value="tree">트리 꾸미기</option></select></label><label>시작<input name="starts" type="datetime-local" required></label><label>종료<input name="ends" type="datetime-local" required></label><button class="panel-primary">이벤트 등록</button></form></details>`);
const adminButton=document.createElement('button');adminButton.id='open-admin';adminButton.textContent='관리';adminButton.hidden=true;document.querySelector('.menu-panel').append(adminButton);
window.addEventListener('lab:access',e=>{adminButton.hidden=!e.detail.admin;});
const adminStatus=adminPanel.dialog.querySelector('output');
async function action(body){try{await request('admin',body);if(body.action.includes('quiz'))window.dispatchEvent(new Event('lab:quiz-updated'));adminStatus.textContent='저장했습니다.';await loadAdmin();}catch(e){adminStatus.textContent=e.message;}}
function row(container,label,buttons){const el=document.createElement('div');el.className='admin-row';const text=document.createElement('p');text.textContent=label;el.append(text);for(const [name,fn] of buttons){const b=document.createElement('button');b.textContent=name;b.onclick=fn;el.append(b);}container.append(el);}
async function loadAdmin(){try{const data=await request('admin');for(const name of ['reports','people','decorations','events','quizzes'])adminPanel.dialog.querySelector('[data-'+name+']').replaceChildren();const get=name=>adminPanel.dialog.querySelector('[data-'+name+']');for(const r of data.reports)row(get('reports'),r.type+' · '+r.reason,[['내용 삭제',()=>action({action:r.type==='chat'?'clear-chat':r.type==='wish'?'remove-wish':'remove-decoration',id:r.targetId})],['처리 완료',()=>action({action:'resolve',id:r.id})]]);for(const p of data.people)row(get('people'),p.name+(p.chat?' · '+p.chat:''),[['채팅 삭제',()=>action({action:'clear-chat',id:p.id})],['이용 제한',()=>action({action:'block',id:p.id})]]);for(const d of data.decorations)row(get('decorations'),d.kind+' · '+d.room,[['삭제',()=>action({action:'remove-decoration',id:d.id})]]);for(const e of data.events)row(get('events'),e.title+' · '+new Date(e.startsAt).toLocaleString('ko-KR'),[['삭제',()=>action({action:'remove-event',id:e.id})]]);const base=await fetch('/content/daily-trivia.json').then(r=>r.json()).catch(()=>[]);const quizMap=new Map(base.map(q=>[q.id,q]));for(const q of data.quizzes)quizMap.set(q.id,q);for(const q of quizMap.values())row(get('quizzes'),q.question,[['편집',()=>fillQuiz(q)],['삭제',()=>action({action:'remove-quiz',id:q.id})]]);}catch(e){adminStatus.textContent=e.message;}}
function fillQuiz(q){const f=adminPanel.dialog.querySelector('[data-quiz-form]');for(const key of ['id','question','category','answer','explanation'])f.elements[key].value=q[key];q.options.forEach((v,i)=>f.elements['option'+(i+1)].value=v);f.elements.sourceTitle.value=q.source.title;f.elements.sourceURL.value=q.source.url;f.elements.disabled.checked=q.disabled;f.scrollIntoView({block:'nearest'});}
adminButton.onclick=()=>{document.querySelector('#park-menu').open=false;adminPanel.open();loadAdmin();};adminPanel.dialog.querySelector('[data-refresh]').onclick=loadAdmin;
adminPanel.dialog.querySelector('[data-quiz-form]').onsubmit=async e=>{e.preventDefault();const v=e.target.elements;await action({action:'save-quiz',id:v.id.value,quiz:{question:v.question.value,category:v.category.value,options:[1,2,3,4].map(n=>v['option'+n].value),answer:Number(v.answer.value),explanation:v.explanation.value,source:{title:v.sourceTitle.value,url:v.sourceURL.value},disabled:v.disabled.checked}});};
adminPanel.dialog.querySelector('[data-event-form]').onsubmit=async e=>{e.preventDefault();const v=e.target.elements;await action({action:'save-event',title:v.title.value,kind:v.kind.value,startsAt:new Date(v.starts.value).getTime(),endsAt:new Date(v.ends.value).getTime()});};
